// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealth Report process liveness.
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// HeadHealth Report process liveness without a response body.
	// (HEAD /healthz)
	HeadHealth(w http.ResponseWriter, r *http.Request)
	// GetMetrics Report process-local Prometheus metrics.
	// (GET /metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// GetReadiness Report service readiness.
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// HeadReadiness Report service readiness without a response body.
	// (HEAD /readyz)
	HeadReadiness(w http.ResponseWriter, r *http.Request)
	// PropagateDeliveryStatus Rebuild and sign one propagated delivery-status notification.
	// (POST /v1/dsn/propagate)
	PropagateDeliveryStatus(w http.ResponseWriter, r *http.Request)
	// CommitDeliveryStatusPropagation Commit one reserved delivery-status propagation coordinate.
	// (POST /v1/dsn/propagate/commit)
	CommitDeliveryStatusPropagation(w http.ResponseWriter, r *http.Request)
	// SignDeliveryStatus Sign one delivery-status report.
	// (POST /v1/dsn/sign)
	SignDeliveryStatus(w http.ResponseWriter, r *http.Request)
	// ProcessMessage Process one inbound DKIM2 message.
	// (POST /v1/process)
	ProcessMessage(w http.ResponseWriter, r *http.Request)
	// ReviseMessage Revise one ordinary-transit DKIM2 message.
	// (POST /v1/revise)
	ReviseMessage(w http.ResponseWriter, r *http.Request)
	// ReviseBatch Revise the external copies of one complete message fanout.
	// (POST /v1/revise/batch)
	ReviseBatch(w http.ResponseWriter, r *http.Request)
	// GetBatchRevisionCapabilities Inspect the enabled batch revision contract without signing.
	// (GET /v1/revise/batch/capabilities)
	GetBatchRevisionCapabilities(w http.ResponseWriter, r *http.Request)
	// SignMessage Sign one originator DKIM2 message.
	// (POST /v1/sign)
	SignMessage(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
